## Code Example

```typescript
// Lightweight enqueue example (pseudo)
import { QueueClient } from "@azure/storage-queue";
async function enqueueEvent(tenantId: string, eventId: string, payload: any) {
  const queue = new QueueClient("<connection-string>", `tenant-${tenantId}-events`);
  const body = Buffer.from(JSON.stringify({ eventId, payload })).toString("base64");
  await queue.sendMessage(body);
}
```

